func TestExcept(t *testing.T) {
	var tests = []struct {
		in  CveContents
		out CveContents
	}{{
		in: CveContents{
			RedHat: []CveContent{{Type: RedHat}},
			Ubuntu: []CveContent{{Type: Ubuntu}},
