// TrivyTypes lists the known Trivy types and any additional sources in the scan.
func (v CveContents) TrivyTypes() CveContentTypes {
	types := append(CveContentTypes(nil), trivyCveContentTypes...)
	var extra CveContentTypes
	for ctype := range v {
		if strings.HasPrefix(string(ctype), "trivy:") && len(CveContentTypes{ctype}.Except(types...)) != 0 {
			extra = append(extra, ctype)
		}
	}
	sort.Slice(extra, func(i, j int) bool { return extra[i] < extra[j] })
	return append(types, extra...)
}

// CveContentTypes has slide of CveContentType
type CveContentTypes []CveContentType

// AllCveContetTypes has all of CveContentTypes
var AllCveContetTypes = append(CveContentTypes{
	Nvd,
	Jvn,
	Fortinet,
	RedHat,
	RedHatAPI,
	Debian,
	DebianSecurityTracker,
	Ubuntu,
	UbuntuAPI,
	Amazon,
	Fedora,
	SUSE,
	WpScan,
	GitHub,
}, trivyCveContentTypes...)

// Except returns CveContentTypes except for given args
func (c CveContentTypes) Except(excepts ...CveContentType) (excepted CveContentTypes) {
	for _, ctype := range c {
		found := false
		for _, except := range excepts {
			if ctype == except {
				found = true
				break
			}
		}
		if !found {
			excepted = append(excepted, ctype)
		}
	}
	return
}

