package pkg

import (
	"reflect"
	"sort"
	"strings"
	"time"

	trivydbTypes "github.com/aquasecurity/trivy-db/pkg/types"

	"github.com/future-architect/vuls/models"
)

// CveContentsFromTrivy keeps each Trivy severity and CVSS source separate.
func CveContentsFromTrivy(cveID string, vul trivydbTypes.Vulnerability, severitySource string) models.CveContents {
	type sourceData struct {
		severity    trivydbTypes.Severity
		hasSeverity bool
		cvss        trivydbTypes.CVSS
	}
	sources := map[string]sourceData{}
	for source, severity := range vul.VendorSeverity {
		name := strings.ToLower(strings.TrimSpace(string(source)))
		if name == "" {
			continue
		}
		data := sources[name]
		data.severity = severity
		data.hasSeverity = true
		sources[name] = data
	}
	for source, cvss := range vul.CVSS {
		name := strings.ToLower(strings.TrimSpace(string(source)))
		if name == "" {
			continue
		}
		data := sources[name]
		data.cvss = cvss
		sources[name] = data
	}
	selectedSource := strings.ToLower(strings.TrimSpace(severitySource))
	if selectedSource != "" {
		if _, found := sources[selectedSource]; !found {
			sources[selectedSource] = sourceData{}
		}
	}
	if len(sources) == 0 {
		sources["unknown"] = sourceData{}
		selectedSource = "unknown"
	}

	references := make(models.References, 0, len(vul.References))
	for _, refURL := range vul.References {
		references = append(references, models.Reference{Source: "trivy", Link: refURL})
	}
	sort.Slice(references, func(i, j int) bool { return references[i].Link < references[j].Link })

	var published, lastModified time.Time
	if vul.PublishedDate != nil {
		published = *vul.PublishedDate
	}
	if vul.LastModifiedDate != nil {
		lastModified = *vul.LastModifiedDate
	}

	contents := models.CveContents{}
	for source, data := range sources {
		ctype := models.CveContentType("trivy:" + source)
		severity := ""
		switch {
		case data.hasSeverity:
			severity = data.severity.String()
		case source == selectedSource && vul.Severity != "":
			severity = vul.Severity
		case data.cvss.V3Score > 0:
			severity = cvss3Severity(data.cvss.V3Score)
		}
		contents[ctype] = []models.CveContent{{
			Type:          ctype,
			CveID:         cveID,
			Title:         vul.Title,
			Summary:       vul.Description,
			Cvss2Score:    data.cvss.V2Score,
			Cvss2Vector:   data.cvss.V2Vector,
			Cvss3Score:    data.cvss.V3Score,
			Cvss3Vector:   data.cvss.V3Vector,
			Cvss3Severity: severity,
			References:    append(models.References(nil), references...),
			CweIDs:        append([]string(nil), vul.CweIDs...),
			Published:     published,
			LastModified:  lastModified,
		}}
	}
	return contents
}

func cvss3Severity(score float64) string {
	switch {
	case score >= 9:
		return "CRITICAL"
	case score >= 7:
		return "HIGH"
	case score >= 4:
		return "MEDIUM"
	case score > 0:
		return "LOW"
	default:
		return ""
	}
}

// MergeCveContents preserves differing reports from the same source across targets.
func MergeCveContents(dst, src models.CveContents) models.CveContents {
	if dst == nil {
		dst = models.CveContents{}
	}
	for ctype, contents := range src {
		for _, content := range contents {
			found := false
			for _, existing := range dst[ctype] {
				if reflect.DeepEqual(existing, content) {
					found = true
					break
				}
			}
			if !found {
				dst[ctype] = append(dst[ctype], content)
			}
		}
	}
	return dst
}
package models

import "testing"

func TestTrivyContentTypesAndAggregations(t *testing.T) {
	types := GetCveContentTypes("trivy")
	for _, want := range []CveContentType{TrivyDebian, TrivyUbuntu, TrivyNVD, TrivyRedHat, TrivyGHSA, TrivyOracleOVAL} {
		found := false
		for _, got := range types {
			if got == want {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("Trivy source %s missing from GetCveContentTypes", want)
		}
	}
	if got := NewCveContentType("trivy:ghsa"); got != TrivyGHSA {
		t.Errorf("NewCveContentType(trivy:ghsa) = %s", got)
	}

	custom := CveContentType("trivy:custom-vendor")
	vinfo := VulnInfo{CveContents: CveContents{
		TrivyDebian: {{Type: TrivyDebian, Title: "Debian title", Summary: "Debian summary", Cvss3Severity: "LOW"}},
		TrivyUbuntu: {{Type: TrivyUbuntu, Title: "Ubuntu title", Summary: "Ubuntu summary", Cvss3Severity: "MEDIUM", Cvss3Score: 5.2, Cvss3Vector: "CVSS:3.1/UBUNTU"}},
		TrivyNVD:    {{Type: TrivyNVD, Title: "NVD title", Summary: "NVD summary", Cvss2Score: 4.3, Cvss2Vector: "AV:N"}},
		custom:      {{Type: custom, Title: "Custom title", Summary: "Custom summary", References: References{{Link: "https://example.org/custom"}}}},
	}}
	for ctype, want := range map[CveContentType]string{
		TrivyDebian: "Debian title", TrivyUbuntu: "Ubuntu title", TrivyNVD: "NVD title", custom: "Custom title",
	} {
		if !hasCveContentStr(vinfo.Titles("en", "debian"), ctype, want) {
			t.Errorf("title for %s missing", ctype)
		}
	}
	for ctype, want := range map[CveContentType]string{
		TrivyDebian: "Debian summary", TrivyUbuntu: "Ubuntu summary", TrivyNVD: "NVD summary", custom: "Custom summary",
	} {
		if !hasCveContentStr(vinfo.Summaries("en", "debian"), ctype, want) {
			t.Errorf("summary for %s missing", ctype)
		}
	}
	if got := vinfo.Cvss2Scores(); len(got) != 1 || got[0].Type != TrivyNVD || got[0].Value.Score != 4.3 || got[0].Value.Vector != "AV:N" {
		t.Errorf("Trivy CVSS v2 missing: %+v", got)
	}
	var ubuntu, debian *CveContentCvss
	for _, score := range vinfo.Cvss3Scores() {
		if score.Type == TrivyUbuntu {
			copy := score
			ubuntu = &copy
		}
		if score.Type == TrivyDebian {
			copy := score
			debian = &copy
		}
	}
	if ubuntu == nil || ubuntu.Value.Score != 5.2 || ubuntu.Value.Vector != "CVSS:3.1/UBUNTU" || ubuntu.Value.CalculatedBySeverity {
		t.Errorf("Ubuntu numeric CVSS v3 missing: %+v", ubuntu)
	}
	if debian == nil || debian.Value.Severity != "LOW" || !debian.Value.CalculatedBySeverity {
		t.Errorf("Debian severity missing: %+v", debian)
	}
	if refs := vinfo.CveContents.References("debian"); len(refs) != 1 || refs[0].Type != custom {
		t.Errorf("custom Trivy references missing: %+v", refs)
	}
}

func hasCveContentStr(values []CveContentStr, ctype CveContentType, value string) bool {
	for _, item := range values {
		if item.Type == ctype && item.Value == value {
			return true
		}
	}
	return false
}

